effect.frag.content:
int sourceIndex = 0;
uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return imageAt(sourceIndex, uv);
}
vec4 over(vec4 front, vec4 back) { return front + back * (1.0 - front.a); }
void main() {
  vec4 color = vec4(0.0);
  for (int i = 0; i < 20; i++) {
    sourceIndex = i;
    float a = TAU * (float(i) / 20.0 + u_progress);
    vec2 center = 0.5 + vec2(cos(a), sin(a)) * 0.27;
    vec2 p = (v_uv - center) / (0.12 + u_amount * 0.12);
    vec4 c = length(p) < 0.5 ? sourceAt(p + 0.5) : vec4(0.0);
    color = over(c, color);
  }
  fragColor = color;
}
